func PnDeskewClear(views *port.Cells, srcview int32) int32 {
	// `nm-view` writes the skew it measures (`nm-deskew`) to the decode view and every view made from it as `vwf-deskew`, which turns every pixel
	// box that is mapped through the view into a rotated one. The OCR evidence (`sc-ev-lines`, `sc-ev-words`) reads the engine's pixel angles as the PAGE's (the
	// pipeline takes a page's tilt out as the median of its lines', D213) and nothing yet takes the view's skew out of them: applied, a scan of lines that fall by
	// 2.77 degrees came out with words 2.8 degrees off in the other direction and every paragraph split. So the Engine's wiring leaves the page's geometry as it
	// was: the rows `nm-view` appended and the source's own go back to no skew (the tracer reads them so too, and agrees with the OCR); the angle is `orf-deskew`'s
	// (the engine's) and `nm-view`'s return is not kept. Answers 0.
	var n int32 = evidence.VwCount(views)
	var v int32 = srcview
	var d int32 = 0
	for v < n {
		d = evidence.VwGet(views, v, evidence.VwfDeskew())
		if d != 0 {
			norm.NmReskew(views, v, 0)
		}
		v += 1
	}
	return 0
}

